    "emailSubject": "Like Added (Tier 2 - Event-Driven)",
    "emailBody": "Push + In-App to recipients who have the app; Email also sent as the reach channel for recipients who have not downloaded the app, so the moment still reaches everyone once without double-touching engaged app users.",
    "inAppExperience": "Reinforce social behavior without creating unnecessary notification noise -- achieved by batching into one summary-with-count push per 15-minute window, not by silently reusing the first event's own message for the whole window.",
    "cta": "Cooldown: 15 minutes \u2022 Suppression: Merge similar social events",
    "comments": "Never report each like/comment individually. Collect activity for this recipient in a 15-minute window; when the window closes, send ONE summary push with a count (e.g. \"5 people commented on your Seedling in the past 15 minutes\"). Tapping the notification takes the user directly to the comments/Seedling. If the window closes with zero events, no push is sent.",
